\ir _helpers/auth_session.sql
begin;
select no_plan();
select pg_temp.set_test_user('',true);
insert into auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select ('98a00000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'authenticated','authenticated','sheets-'||n||'@example.invalid',now(),'{}','{}',now(),now() from generate_series(1,2) n;
update public.users u set legal_acceptance_version=p.version,legal_acceptance_digest=p.digest from public.legal_policy p where p.id and u.id in ('98a00000-0000-0000-0000-000000000001','98a00000-0000-0000-0000-000000000002');
insert into public.exercise_catalog(id,provider,provider_exercise_id,name,primary_muscle,muscles,category,instructions,status)
select ('98c00000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'evolutus_dataset','sheet-'||n,'Oficial '||n,'peito',array['peito'],case when n=3 then 'cardio' else 'forca' end,array['Empurre'],'published' from generate_series(1,3) n;
insert into public.exercises(id,user_id,name,muscle_group,source,provider,provider_exercise_id,catalog_id,type)
select ('98e00000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'98a00000-0000-0000-0000-000000000001','Oficial '||n,'Peito','catalog','evolutus_dataset','sheet-'||n,('98c00000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,case when n=3 then 'cardio' else 'strength' end from generate_series(1,3)n;
insert into public.exercises(id,user_id,name,muscle_group) values('98e00000-0000-0000-0000-000000000004','98a00000-0000-0000-0000-000000000001','Legado','Peito'),('98e00000-0000-0000-0000-000000000005','98a00000-0000-0000-0000-000000000002','Outra conta','Peito');
create temp table counts_before as select (select count(*) from public.workouts) workouts,(select count(*) from public.economy_transactions) coins;
select pg_temp.set_test_user('98a00000-0000-0000-0000-000000000001',true);
set local role authenticated;
select throws_ok($$insert into public.workout_sheets(user_id,name,create_request_id) values(auth.uid(),'Bypass',gen_random_uuid())$$,'42501',null,'escrita direta negada');
select throws_ok($$select public.create_workout_sheet(gen_random_uuid(),'Outra conta',null,'','{}','[]','98a00000-0000-0000-0000-000000000002')$$,'P0001','SHEET_ACCOUNT_CHANGED','criação de formulário de outra conta é rejeitada');
create temp table saved as select public.create_workout_sheet('98000000-0000-0000-0000-000000000001',' A ','forca','Meta',array[1,3]::smallint[]) result;
select is((select count(*)::int from public.workout_sheets),1,'cria ficha própria');
select is((select name from public.workout_sheets),'A','normaliza nome');
select lives_ok($$select public.create_workout_sheet('98000000-0000-0000-0000-000000000001',' A ','forca','Meta',array[1,3]::smallint[])$$,'retry de criação com o mesmo conteúdo');
select is((select count(*)::int from public.workout_sheets),1,'retry não duplica');
select is((select revision from public.workout_sheets),(select (result->>'revision')::bigint from saved),'retry idêntico não grava nem incrementa revisão');
-- P0 (auditoria 2026-11-10): um retry com o MESMO request_id mas conteúdo DIFERENTE do que foi
-- persistido na 1ª tentativa (edição feita entre o timeout da confirmação e a retentativa) precisa
-- reconciliar para o conteúdo atual -- nunca descartá-lo silenciosamente a favor do snapshot antigo.
select lives_ok($$select public.create_workout_sheet('98000000-0000-0000-0000-000000000001','A editada',null,'',array[]::smallint[])$$,'retry com conteúdo diferente reconcilia em vez de descartar a edição');
select is((select name from public.workout_sheets),'A editada','reconciliação aplica o nome mais recente, não o da 1ª tentativa');
select is((select goal from public.workout_sheets),null,'reconciliação aplica o objetivo mais recente (removido)');
select is((select weekdays from public.workout_sheets),'{}'::smallint[],'reconciliação aplica os dias mais recentes (removidos)');
select isnt((select revision from public.workout_sheets),(select (result->>'revision')::bigint from saved),'conteúdo reconciliado grava e incrementa a revisão, não é tratado como retry idêntico');
select throws_ok($$select public.get_my_workout_sheet((select (result->>'id')::uuid from saved),true)$$,'P0001','SHEET_NOT_READY','rascunho não inicia');
select lives_ok($$select public.save_workout_sheet((select (result->>'id')::uuid from saved),(select revision from public.workout_sheets),'{"name":"A","goal":"forca","goal_description":"Meta","weekdays":[1,3]}','[{"exercise_id":"98e00000-0000-0000-0000-000000000001","target_sets":3,"reps_min":8,"reps_max":12}]')$$,'salva itens transacionalmente');
create temp table current_sheet as select id,revision from public.workout_sheets;
create temp table item_before as select id from public.workout_sheet_exercises;
select lives_ok($$select public.get_my_workout_sheet((select id from current_sheet),true)$$,'servidor confirma execução');
select throws_ok($$select public.save_workout_sheet((select id from current_sheet),1,'{}','[]')$$,'P0001','SHEET_VERSION_CONFLICT','versão antiga não escreve');
select throws_ok(format($$select public.save_workout_sheet((select id from current_sheet),(select revision from current_sheet),'%s','[{"exercise_id":"98e00000-0000-0000-0000-000000000001"}]')$$,payload),'P0001','SHEET_INVALID_PAYLOAD','metadados inválidos: '||payload)
from (values ('{"name":" ","weekdays":[]}'),('{"name":"A","weekdays":[1,1]}'),('{"name":"A","weekdays":[7]}'),('{"name":"A","weekdays":[null]}'),('{"name":"A","goal":"hacked","weekdays":[]}')) t(payload);
select throws_ok(format($$select public.save_workout_sheet((select id from current_sheet),(select revision from current_sheet),'{"name":"A","weekdays":[]}','[{"exercise_id":"98e00000-0000-0000-0000-000000000001",%s}]')$$,payload),'P0001','SHEET_INVALID_TARGET','metas inválidas: '||payload)
from (values ('"target_sets":11'),('"reps_min":13,"reps_max":8'),('"rest_seconds":901'),('"target_duration_minutes":10'),('"target_distance_km":1')) t(payload);
select throws_ok($$select public.save_workout_sheet((select id from current_sheet),(select revision from current_sheet),'{"name":"A","weekdays":[]}','[{"exercise_id":"98e00000-0000-0000-0000-000000000004"}]')$$,'P0001','SHEET_EXERCISE_UNAVAILABLE','legado não pode entrar');
select throws_ok($$select public.save_workout_sheet((select id from current_sheet),(select revision from current_sheet),'{"name":"A","weekdays":[]}','[{"exercise_id":"98e00000-0000-0000-0000-000000000005"}]')$$,'P0001','SHEET_EXERCISE_UNAVAILABLE','outra conta não pode entrar');
select throws_ok($$select public.save_workout_sheet((select id from current_sheet),(select revision from current_sheet),'{"name":"A","weekdays":[]}','[{"exercise_id":"98e00000-0000-0000-0000-000000000001"},{"exercise_id":"98e00000-0000-0000-0000-000000000001"}]')$$,'P0001','SHEET_DUPLICATE_EXERCISE','duplicata na ficha negada');
select is((select revision from public.workout_sheets),(select revision from current_sheet),'falhas não alteram revisão');
select is((select id from public.workout_sheet_exercises),(select id from item_before),'falhas não alteram itens');
select throws_ok($$delete from public.exercises where id='98e00000-0000-0000-0000-000000000001'$$,'23503',null,'referência impede exclusão da biblioteca');
select lives_ok($$select public.duplicate_workout_sheet((select id from current_sheet),'98000000-0000-0000-0000-000000000002')$$,'duplica atomicamente');
select lives_ok($$select public.duplicate_workout_sheet((select id from current_sheet),'98000000-0000-0000-0000-000000000002')$$,'retry duplicação');
select is((select count(*)::int from public.workout_sheets),2,'duplicação idempotente');
select is((select count(*)::int from public.workout_sheet_exercises),2,'itens clonados uma vez');
select throws_ok($$select public.reorder_workout_sheets(array[(select id from current_sheet)])$$,'P0001','SHEET_INVALID_ORDER','reorder exige conjunto completo');
select lives_ok($$select public.reorder_workout_sheets(array(select id from public.workout_sheets order by id desc))$$,'reorder atômico');
select lives_ok($$select public.set_workout_sheet_archived((select id from current_sheet),true,(select revision from public.workout_sheets where id=(select id from current_sheet)))$$,'arquiva ficha');
select throws_ok($$select public.get_my_workout_sheet((select id from current_sheet),true)$$,'P0001','SHEET_NOT_READY','arquivada não inicia');
select lives_ok($$select public.set_workout_sheet_archived((select id from current_sheet),true,1)$$,'arquivar já arquivada é idempotente');
select lives_ok($$select public.set_workout_sheet_archived((select id from current_sheet),false,(select revision from public.workout_sheets where id=(select id from current_sheet)))$$,'restaura ficha');
select is((select count(distinct sort_order)::int from public.workout_sheets where archived_at is null),(select count(*)::int from public.workout_sheets where archived_at is null),'restauração após reorder não reutiliza posição ativa');
reset role;
select pg_temp.set_test_user('98a00000-0000-0000-0000-000000000002',true);
set local role authenticated;
select is((select count(*)::int from public.workout_sheets),0,'B não lê fichas de A');
select is((select count(*)::int from public.workout_sheet_exercises),0,'B não lê itens de A');
select throws_ok($$select public.get_my_workout_sheet((select id from current_sheet),true)$$,'P0001','SHEET_NOT_FOUND','B não inicia ficha de A');
select throws_ok($$select public.save_workout_sheet((select id from current_sheet),1,'{}','[]')$$,'P0001','SHEET_NOT_FOUND','B não edita ficha de A');
select throws_ok($$select public.duplicate_workout_sheet((select id from current_sheet),gen_random_uuid())$$,'P0001','SHEET_NOT_FOUND','B não duplica ficha de A');
select throws_ok($$select public.set_workout_sheet_archived((select id from current_sheet),true,1)$$,'P0001','SHEET_NOT_FOUND','B não arquiva ficha de A');
reset role;
select pg_temp.set_test_user('',true);
update public.exercise_catalog set status='withdrawn' where provider_exercise_id in ('sheet-1','sheet-2');
select pg_temp.set_test_user('98a00000-0000-0000-0000-000000000001',true);
set local role authenticated;
select is((public.get_my_workout_sheet((select id from current_sheet))->'items'->0->>'available')::boolean,false,'retirado permanece visível e indisponível');
select throws_ok($$select public.get_my_workout_sheet((select id from current_sheet),true)$$,'P0001','SHEET_NOT_READY','retirado não inicia');
select throws_ok($$select public.save_workout_sheet((select id from current_sheet),(select revision from public.workout_sheets where id=(select id from current_sheet)),'{"name":"A","weekdays":[]}','[{"exercise_id":"98e00000-0000-0000-0000-000000000002"}]')$$,'P0001','SHEET_EXERCISE_UNAVAILABLE','não anexa retirado');
select lives_ok($$select public.save_workout_sheet((select id from current_sheet),(select revision from public.workout_sheets where id=(select id from current_sheet)),'{"name":"A editada","weekdays":[]}','[{"exercise_id":"98e00000-0000-0000-0000-000000000001","note":"Substituir"}]')$$,'retirado existente permite editar planejamento');
select throws_ok($$select public.duplicate_workout_sheet((select id from current_sheet),gen_random_uuid())$$,'P0001','SHEET_EXERCISE_UNAVAILABLE','duplicação não anexa retirados a uma nova ficha');
-- Cardinality, unchanged saves and active limits remain enforced by the server.
select throws_ok($$select public.save_workout_sheet((select id from current_sheet),(select revision from public.workout_sheets where id=(select id from current_sheet)),'{"name":"A","weekdays":[]}',(select jsonb_agg(jsonb_build_object('exercise_id',gen_random_uuid())) from generate_series(1,41)))$$,'P0001','SHEET_INVALID_PAYLOAD','limite de 40 itens validado antes de qualquer escrita');
create temp table unchanged_before as select revision from public.workout_sheets where id=(select id from current_sheet);
select lives_ok($$select public.save_workout_sheet((select id from current_sheet),(select revision from unchanged_before),'{"name":"A editada","weekdays":[]}','[{"exercise_id":"98e00000-0000-0000-0000-000000000001","note":"Substituir"}]')$$,'salvar sem mudança é permitido sem gravar');
select is((select revision from public.workout_sheets where id=(select id from current_sheet)),(select revision from unchanged_before),'sem mudança não incrementa revisão');
select throws_ok($$update public.workout_sheets set name='Bypass'$$,'42501',null,'update direto negado');
select throws_ok($$delete from public.workout_sheets$$,'42501',null,'delete direto negado');
select throws_ok($$insert into public.workout_sheet_exercises(sheet_id,user_id,exercise_id,sort_order) values((select id from current_sheet),auth.uid(),'98e00000-0000-0000-0000-000000000003',0)$$,'42501',null,'insert direto de item negado');
select lives_ok($$select public.create_workout_sheet(gen_random_uuid(),'Ficha '||n) from generate_series(1,38) n$$,'até 40 fichas ativas');
select is((select count(*)::int from public.workout_sheets where archived_at is null),40,'40 fichas ativas');
select throws_ok($$select public.create_workout_sheet(gen_random_uuid(),'Excesso')$$,'P0001','SHEET_LIMIT_REACHED','limite ativo no servidor');
select throws_ok($$select public.duplicate_workout_sheet((select id from current_sheet),gen_random_uuid())$$,'P0001','SHEET_LIMIT_REACHED','duplicação respeita limite');
select lives_ok($$select public.set_workout_sheet_archived((select id from current_sheet),true,(select revision from public.workout_sheets where id=(select id from current_sheet)))$$,'arquivar libera uma vaga');
select lives_ok($$select public.create_workout_sheet('98000000-0000-0000-0000-000000000099','Vaga')$$,'criação após arquivar');
select throws_ok($$select public.set_workout_sheet_archived((select id from current_sheet),false,(select revision from public.workout_sheets where id=(select id from current_sheet)))$$,'P0001','SHEET_LIMIT_REACHED','restauração também respeita limite');
select is(jsonb_array_length(public.list_my_workout_sheets()),40,'lista ativa limitada');
select is(jsonb_array_length(public.list_my_workout_sheets(true)),1,'lista arquivada separada');
explain (analyze,buffers) select id,name from public.workout_sheets where user_id=auth.uid() and archived_at is null order by sort_order,id limit 40;
explain (analyze,buffers) select exercise_id,sort_order from public.workout_sheet_exercises where sheet_id=(select id from current_sheet) order by sort_order,id;
reset role;
select pg_temp.revoke_test_session('98a00000-0000-0000-0000-000000000001');
set local role authenticated;
select is((select count(*)::int from public.workout_sheets),0,'sessão revogada não lê');
select throws_ok($$select public.list_my_workout_sheets()$$,'P0001','SESSION_REVOKED','revogada não lista via RPC');
select throws_ok($$select public.create_workout_sheet(gen_random_uuid(),'X')$$,'P0001','SESSION_REVOKED','revogada não cria');
select throws_ok($$select public.save_workout_sheet((select id from current_sheet),1,'{}','[]')$$,'P0001','SESSION_REVOKED','revogada não salva');
reset role;
select is((select count(*) from public.workouts),(select workouts from counts_before),'planejamento não altera treinos');
select is((select count(*) from public.economy_transactions),(select coins from counts_before),'planejamento não altera recompensas');
select ok(not has_function_privilege('anon','public.get_my_workout_sheet(uuid,boolean)','EXECUTE'),'anônimo sem execução');
select ok(not has_function_privilege('authenticated','private.sheet_exercise_available(uuid,uuid)','EXECUTE'),'helper privado não exposto');
select pg_temp.set_test_user('',true);
select lives_ok($$delete from public.users where id='98a00000-0000-0000-0000-000000000001'$$,'exclusão autorizada da conta limpa planejamento antes das FKs RESTRICT');
select is((select count(*)::int from public.workout_sheets where user_id='98a00000-0000-0000-0000-000000000001'),0,'nenhuma ficha órfã após exclusão de conta');
select is((select count(*)::int from public.workout_sheet_exercises where user_id='98a00000-0000-0000-0000-000000000001'),0,'nenhum item órfão após exclusão de conta');
select finish();
rollback;
